<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { onBeforeRouteLeave } from 'vue-router'
import { Modal, message } from 'ant-design-vue'
import { canIam, iamMessage } from '@/services/iamAccess'
import { loadRoles, roleCommand, roleQuery, assertRolePreview, type AppRole, type RolePreview } from '@/services/iamRoles'
import OwnAccountVerification from '@/components/account/OwnAccountVerification.vue'
import { useAccountProof } from '@/composables/useAccountProof'
const items=ref<AppRole[]>([]), selected=ref('staff'), loading=ref(true), busy=ref(false), error=ref(''), editing=ref(false), checked=ref<string[]>([]), preview=ref<RolePreview|null>(null), restore=ref('')
const role=computed(()=>items.value.find(row=>row.role_key===selected.value)), proof=useAccountProof(()=>{preview.value=null})
const groups=[['self','本人查询'],['board','部门面板'],['records','员工考勤'],['company','公司考勤'],['schedule','班次与排班'],['correction','考勤更正'],['import','导入'],['rules','规则与重算'],['reports','报表'],['export','导出']]
const dirty=computed(()=>editing.value && JSON.stringify([...checked.value].sort())!==JSON.stringify(role.value?.draft_features.map(row=>row.operation_id).sort()))
function reset(){checked.value=role.value?.draft_features.map(row=>row.operation_id)||[];preview.value=null;restore.value=''}
async function load(preserve=false){loading.value=true;error.value='';try{items.value=await loadRoles();if(!preserve)reset();preview.value=null}catch(e){error.value=iamMessage(e)}finally{loading.value=false}}
async function leave(){if(busy.value)return false;if(!dirty.value)return true;return new Promise<boolean>(resolve=>Modal.confirm({title:'放弃尚未保存的角色草稿？',okText:'放弃草稿',cancelText:'继续编辑',onOk:()=>resolve(true),onCancel:()=>resolve(false)}))}
async function select(key:string){if(!await leave())return;selected.value=key;editing.value=false;reset()}
async function save(){if(!role.value||busy.value||!proof.valid.value)return;busy.value=true;error.value='';try{await roleCommand('save_role_draft',{role_key:selected.value,expected_draft_version:role.value.draft_version,features:role.value.registry.filter(row=>checked.value.includes(row.operation_id)).map(({operation_id,scope_binding})=>({operation_id,scope_binding})),request_id:crypto.randomUUID()});editing.value=false;await load();message.success('草稿已保存，员工现有权限尚未改变。')}catch(e){error.value=iamMessage(e)}finally{busy.value=false}}
async function prepare(){if(!role.value||busy.value)return;busy.value=true;error.value='';try{preview.value=assertRolePreview(await roleCommand<RolePreview>('preview_role_publish',{role_key:selected.value,expected_draft_version:role.value.draft_version,expected_release:role.value.published_release}))}catch(e){error.value=iamMessage(e)}finally{busy.value=false}}
async function publish(){if(!role.value||!preview.value||busy.value||!proof.valid.value)return;busy.value=true;error.value='';try{await roleCommand('publish_role',{role_key:selected.value,expected_draft_version:role.value.draft_version,expected_release:role.value.published_release,context_revision:preview.value.context_revision,request_id:crypto.randomUUID()});proof.invalidate();await load();message.success('角色已发布，后续请求使用新版本。')}catch(e){error.value=iamMessage(e);preview.value=null}finally{busy.value=false}}
async function restoreDraft(){if(!role.value||!restore.value||busy.value||!proof.valid.value)return;busy.value=true;error.value='';try{await roleCommand('restore_role_release',{role_key:selected.value,source_release:restore.value,expected_draft_version:role.value.draft_version,request_id:crypto.randomUUID()});editing.value=false;await load();message.success('历史内容已恢复为草稿，请核对影响后发布。')}catch(e){error.value=iamMessage(e)}finally{busy.value=false}}
onBeforeRouteLeave(leave);onMounted(()=>load())
</script>
<template><section class="roles-view"><div class="iam-heading"><div><h1>角色与权限</h1><p>先选角色，再修改功能。保存草稿后，预览影响并确认发布。</p></div><a-select value="attendance" aria-label="角色所属应用" style="width:180px"><a-select-option value="attendance">考勤管理</a-select-option></a-select></div><a-alert v-if="error" :message="error" type="warning" show-icon/><a-button v-if="error" :disabled="busy" @click="load(editing)">读取最新版本，保留编辑</a-button><a-skeleton v-if="loading" active/><div v-else class="role-layout"><aside class="iam-panel"><button v-for="item in items" :key="item.role_key" :aria-pressed="selected===item.role_key" @click="select(item.role_key)"><strong>{{item.title}}</strong><small>{{item.published_revision ? `已发布 v${item.published_revision}` : '尚未发布'}}</small></button></aside><section v-if="role" class="iam-panel"><h2>{{role.title}}</h2><p>范围上限：{{role.boundary_kind==='SELF'?'仅本人':role.boundary_kind==='DEPARTMENT'?'明确指定的负责部门，不自动包含下级':'明确指定的一个公司'}}。本人查询始终只看本人。</p><p>当前发布 v{{role.published_revision}} · 草稿 v{{role.draft_version}}</p><a-alert v-if="role.registry.some(row=>row.allowed&&!row.integrated)" type="info" message="部分业务功能仍在接入。下方保留完整功能清单；含待接入功能的草稿不能发布。"/><OwnAccountVerification v-if="canIam('iam.roles.edit')||canIam('iam.roles.publish')" password-only @verified="proof.sync" @invalidated="proof.invalidate"/><div class="role-groups"><section v-for="[key,title] in groups" :key="key"><h3>{{title}}</h3><label v-for="row in role.registry.filter(row=>row.group===key)" :key="row.operation_id"><a-checkbox :checked="checked.includes(row.operation_id)" :disabled="!editing||busy||!row.allowed" @change="checked=checked.includes(row.operation_id)?checked.filter(id=>id!==row.operation_id):[...checked,row.operation_id]">{{row.title}}</a-checkbox><small>{{!row.allowed?'超过此角色上限':!row.integrated?row.reason:row.scope_binding==='SELF'?'仅本人':'绑定到员工明确指定的负责范围'}}</small></label></section></div><div class="actions"><template v-if="editing"><a-button :disabled="busy" @click="editing=false;reset()">取消修改</a-button><a-button type="primary" :loading="busy" :disabled="!dirty||!proof.valid.value" @click="save">保存草稿</a-button></template><template v-else><a-button v-if="canIam('iam.roles.edit')" :disabled="busy" @click="reset();editing=true">修改功能</a-button><a-button v-if="canIam('iam.roles.publish')" :loading="busy" @click="prepare">预览发布影响</a-button></template></div><section v-if="preview" class="publish-preview" aria-live="polite"><h3>发布影响</h3><p>引用该角色 {{preview.reference_count}} 人；实际权限变化 {{preview.effective_changed_count}} 人。</p><p v-for="person in preview.members" :key="person.employee">{{person.name}}：{{person.changed?'权限将变化':'当前实际权限保持'}}{{person.reason ? '，'+person.reason : ''}}</p><a-button :disabled="busy" @click="preview=null">取消发布</a-button><a-button type="primary" :loading="busy" :disabled="!proof.valid.value||!preview.changed" @click="publish">确认发布</a-button></section><details v-if="role.releases.length&&canIam('iam.roles.edit')"><summary>从历史发布内容恢复草稿</summary><a-select v-model:value="restore" aria-label="历史发布版本" style="min-width:200px"><a-select-option v-for="release in role.releases" :key="release.name" :value="release.name">v{{release.revision}} · {{release.published_at}}</a-select-option></a-select><a-button :disabled="!restore||!proof.valid.value||busy" @click="restoreDraft">恢复为草稿</a-button><p>恢复仍需重新预览、确认发布才会改变员工权限。</p></details></section></div></section></template>
<style scoped>.roles-view{display:grid;gap:16px}.role-layout{display:grid;grid-template-columns:220px minmax(0,1fr);gap:24px}.role-layout aside{display:grid;gap:8px;align-content:start}.role-layout aside button{display:grid;gap:6px;text-align:left;padding:14px;border:1px solid var(--hbos-border-subtle);background:transparent;border-radius:10px;cursor:pointer;color:inherit;font:inherit}.role-layout aside button[aria-pressed=true]{background:var(--hbos-bg-elevated);border-color:var(--hbos-brand-violet)}small{font-size:14px;color:var(--hbos-text-secondary)}.role-groups{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;margin:20px 0}.role-groups section{border:1px solid var(--hbos-border-subtle);border-radius:12px;padding:16px}.role-groups label{display:grid;gap:4px;margin:10px 0}.actions{display:flex;gap:12px;position:sticky;bottom:0;background:var(--hbos-surface-solid);padding:16px 0}.publish-preview{border:1px solid var(--hbos-border-strong);padding:20px;border-radius:12px;margin:16px 0}.publish-preview .ant-btn{margin-right:12px}details{margin-top:20px}@media(max-width:800px){.role-layout,.role-groups{grid-template-columns:1fr}}</style>
